package br.com.studyou.data.repository

import br.com.studyou.domain.model.CrosswordPuzzle
import br.com.studyou.domain.model.Flashcard
import br.com.studyou.domain.model.GameAttempt
import br.com.studyou.domain.model.GameSummary
import br.com.studyou.domain.model.GameType
import br.com.studyou.domain.model.GuessWordPuzzle
import br.com.studyou.domain.model.QuizQuestion
import br.com.studyou.domain.model.WordFormingPuzzle
import br.com.studyou.domain.repository.GameRepository

/** Serves the games generated by the backend at upload time, held in [generatedGamesStore]. */
class GameRepositoryImpl(private val generatedGamesStore: GeneratedGamesStore) : GameRepository {

    override suspend fun getGames(fileId: String): List<GameSummary> {
        val games = generatedGamesStore.get(fileId) ?: return emptyList()
        return listOf(
            GameSummary(
                type = GameType.QUIZ,
                title = "Quiz",
                description = "Perguntas de múltipla escolha sobre o conteúdo do arquivo.",
                resultLabel = "Ainda não jogado",
                played = false
            ),
            GameSummary(
                type = GameType.FLASHCARDS,
                title = "Flashcards",
                description = "Revise os conceitos principais em cartões de memorização.",
                resultLabel = "Ainda não jogado",
                played = false
            ),
            GameSummary(
                type = GameType.GUESS_WORD,
                title = "Termo",
                description = "Descubra a palavra-chave em até ${games.guessWord.maxAttempts} tentativas.",
                resultLabel = "Ainda não jogado",
                played = false
            ),
            GameSummary(
                type = GameType.CROSSWORD,
                title = "Cruzamento",
                description = "Toque nas letras para formar palavras e preencher a cruzadinha.",
                resultLabel = "Ainda não jogado",
                played = false
            ),
            GameSummary(
                type = GameType.WORD_FORMING,
                title = "Forma-Palavras",
                description = "Forme o máximo de palavras com as letras disponíveis.",
                resultLabel = "Ainda não jogado",
                played = false
            )
        )
    }

    override suspend fun getQuiz(fileId: String): List<QuizQuestion> =
        generatedGamesStore.get(fileId)?.quiz.orEmpty()

    override suspend fun getFlashcards(fileId: String): List<Flashcard> =
        generatedGamesStore.get(fileId)?.flashcards.orEmpty()

    override suspend fun getGuessWordPuzzle(fileId: String): GuessWordPuzzle? =
        generatedGamesStore.get(fileId)?.guessWord

    override suspend fun getCrosswordPuzzle(fileId: String): CrosswordPuzzle? =
        generatedGamesStore.get(fileId)?.crossword

    override suspend fun getWordFormingPuzzle(fileId: String): WordFormingPuzzle? =
        generatedGamesStore.get(fileId)?.wordForming

    override suspend fun saveAttempt(attempt: GameAttempt) {
        // TODO: persist the attempt (score, XP, streak) to the backend/local database so it
        // shows up in the history and profile screens.
    }
}
